 c.execute('SET TRANSACTION READ ONLY');identity=c.execute("SELECT current_database() AS database,system_identifier::text AS cluster,current_setting('transaction_read_only') AS readonly FROM pg_control_system()").fetchone();assert identity==comparisons['identity']
 rels=c.execute("SELECT n.nspname||'.'||r.relname AS relation,r.relkind,r.relrowsecurity,r.relforcerowsecurity,pg_get_userbyid(r.relowner) AS owner,r.relhasrules,r.relhasindex,r.relhassubclass FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname||'.'||r.relname=ANY(%s) ORDER BY relation",(relations,)).fetchall();assert len(rels)==len(relations)
 rules=c.execute("SELECT n.nspname||'.'||r.relname AS relation,w.rulename,w.ev_type,w.ev_enabled,w.is_instead,encode(sha256(convert_to(pg_get_ruledef(w.oid),'UTF8')),'hex') AS rule_hash,pg_get_ruledef(w.oid) AS body FROM pg_rewrite w JOIN pg_class r ON r.oid=w.ev_class JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname||'.'||r.relname=ANY(%s) ORDER BY relation,w.rulename",(relations,)).fetchall()
 indexes=c.execute("""SELECT n.nspname||'.'||r.relname AS relation,i.indexrelid::regclass::text AS index,idx.i AS ordinal,am.amname,ocn.nspname AS opclass_schema,oc.opcname,oc.opcintype::regtype::text AS input_type,oc.opcfamily::text AS family_oid,i.indisvalid,i.indisready,i.indisunique,pg_get_expr(i.indexprs,i.indrelid) AS expression,pg_get_expr(i.indpred,i.indrelid) AS predicate FROM pg_index i JOIN pg_class r ON r.oid=i.indrelid JOIN pg_namespace n ON n.oid=r.relnamespace JOIN pg_class ir ON ir.oid=i.indexrelid JOIN pg_am am ON am.oid=ir.relam CROSS JOIN LATERAL generate_subscripts(i.indclass,1) idx(i) JOIN pg_opclass oc ON oc.oid=i.indclass[idx.i] JOIN pg_namespace ocn ON ocn.oid=oc.opcnamespace WHERE n.nspname||'.'||r.relname=ANY(%s) ORDER BY relation,index,idx.i""",(relations,)).fetchall()
 families=sorted({x['family_oid'] for x in indexes})
 support=c.execute("""SELECT fn.nspname AS family_schema,f.opfname,p.amprocnum,p.amproclefttype::regtype::text AS left_type,p.amprocrighttype::regtype::text AS right_type,pr.oid::regprocedure::text AS function,pn.nspname AS function_schema,l.lanname AS language,pr.prosrc AS symbol,pr.probin,pr.prosupport::regproc::text AS planner_support,pg_get_userbyid(pr.proowner) AS owner,encode(sha256(convert_to(pr.prosrc,'UTF8')),'hex') AS body_hash FROM pg_amproc p JOIN pg_opfamily f ON f.oid=p.amprocfamily JOIN pg_namespace fn ON fn.oid=f.opfnamespace JOIN pg_proc pr ON pr.oid=p.amproc JOIN pg_namespace pn ON pn.oid=pr.pronamespace JOIN pg_language l ON l.oid=pr.prolang WHERE p.amprocfamily::text=ANY(%s) ORDER BY family_schema,f.opfname,p.amprocnum,left_type,right_type""",(families,)).fetchall()
 op_planning=c.execute("""SELECT op.oid::regoperator::text AS operator,op.oprrest::regproc::text AS restriction_estimator,op.oprjoin::regproc::text AS join_estimator,op.oprcode::regprocedure::text AS function,p.prosupport::regproc::text AS function_planner_support FROM pg_operator op JOIN pg_proc p ON p.oid=op.oprcode WHERE op.oid::text=ANY(%s) ORDER BY operator""",(sorted({x['operator_oid'] for x in comparisons['bindings']}),)).fetchall()
 preload={name:c.execute("SELECT current_setting(%s) AS value",(name,)).fetchone()['value'] for name in ('shared_preload_libraries','session_preload_libraries','local_preload_libraries')};extensions=c.execute("SELECT e.extname,e.extversion,n.nspname AS schema,pg_get_userbyid(e.extowner) AS owner FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace ORDER BY e.extname").fetchall()
 out=dict(authority='AOS-001691',identity=identity,source_comparison_sha256=hashlib.sha256((B/'all-ri-comparisons-1691.json').read_bytes()).hexdigest(),relation_count=len(relations),relations=rels,rewrite_rules=rules,indexes=indexes,index_family_support=support,operator_planning=op_planning,preload=preload,extensions=extensions,custom_opclasses=[x for x in indexes if x['opclass_schema']!='pg_catalog'],custom_index_support=[x for x in support if x['family_schema']!='pg_catalog' or x['function_schema']!='pg_catalog' or x['language'] not in ('internal','c')],index_expressions_or_predicates=[x for x in indexes if x['expression'] or x['predicate']],native_planner_or_comparison_executed=False,native_effect_approved=False,formal_binary_provenance_verified=False,execution_allowed=False)
 (B/'ri-read-surface-1691.json').open('x').write(json.dumps(out,indent=2)+'\n');print(json.dumps(dict(relation_count=len(relations),rewrite_rules=len(rules),index_columns=len(indexes),support_function_bindings=len(support),custom_opclasses=len(out['custom_opclasses']),custom_index_support=len(out['custom_index_support']),index_expressions_or_predicates=len(out['index_expressions_or_predicates']),preload=preload,extensions=extensions,execution_allowed=False)))
